(() => {
  'use strict';
  const $ = (selector, root = document) => root.querySelector(selector);
  const app = () => window.go?.main?.App;
  const state = { boot:null, mine:[], received:[], selected:null, view:'home', status:'all', period:'all', seen:new Set(), initialReceived:true };
  const content = $('#content');
  const statusText = {open:'Aberto', in_progress:'Em andamento', waiting:'Aguardando', done:'Concluído'};
  const priorityText = {low:'Baixa', normal:'Normal', high:'Alta'};

  function escape(value=''){ return String(value).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
  function date(value){ if(!value) return '—'; const d = new Date(value); return Number.isNaN(d) ? value : d.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}); }
  function relative(value){ const ms = Date.now()-new Date(value).getTime(); const m=Math.max(0,Math.round(ms/60000)); if(m<1)return 'agora'; if(m<60)return `${m} min`; const h=Math.round(m/60); if(h<24)return `${h} h`; return `${Math.round(h/24)} dias`; }
  function setConnection(connected, message=''){ const el=$('#connection'); el.className=`connection ${connected?'':'offline'}`; el.innerHTML=`<i></i><span>${connected?'Conectado':'Sem conexão'}</span>`; if(message) el.title=message; }
  function ticketStatus(t){ return `<span class="chip ${t.status==='in_progress'?'progress':t.status==='waiting'?'waiting':''}">${escape(statusText[t.status]||t.status)}</span>`; }
  function filteredMine(){ const now=Date.now(); return state.mine.filter(t=>{ if(state.status!=='all' && t.status!==state.status)return false; const age=now-new Date(t.created_at).getTime(); return state.period==='all'||(state.period==='today'&&age<864e5)||(state.period==='week'&&age<7*864e5)||(state.period==='month'&&age<30*864e5); }); }
  function renderSidebar(){ const list=$('#mine-list'); const items=filteredMine(); list.innerHTML=items.length?items.map(t=>`<button class="ticket-card ${state.selected?.id===t.id?'selected':''}" data-ticket="${escape(t.id)}"><div class="ticket-meta"><span>${escape(t.code)}</span><span class="priority ${t.priority==='high'?'high':''}">${escape(priorityText[t.priority]||t.priority)}</span></div><h4>${escape(t.title)}</h4>${ticketStatus(t)}<p>${relative(t.created_at)} · ${escape(t.owner_name_snapshot||state.boot?.hostname||'Este PC')}</p></button>`).join(''):'<p class="muted" style="padding:14px 2px">Nenhum chamado neste filtro.</p>';
    $('#count-all').textContent=state.mine.length; $('#count-open').textContent=state.mine.filter(t=>t.status!=='done').length; $('#count-done').textContent=state.mine.filter(t=>t.status==='done').length;
    const showReceived=state.boot?.receive_departments?.length>0; $('#received-nav').classList.toggle('hidden',!showReceived); $('#received-count').textContent=state.received.filter(t=>t.status!=='done').length;
    $$('[data-ticket]').forEach(el=>el.onclick=()=>openTicket(el.dataset.ticket));
  }
  function $$(s,r=document){return [...r.querySelectorAll(s)];}
  function renderHome(){ content.innerHTML=`<div class="page empty-state"><h1>Meus chamados</h1><p class="subtitle">Abra um chamado com descrição e anexo, checklist opcional, e acompanhe a resposta por aqui.</p><button class="big-action" data-view="new">Abrir novo chamado</button></div>`; bindViews(); }
  function renderNew(){ const options=(state.boot?.departments||[]).filter(d=>d.active).map(d=>`<option value="${escape(d.slug)}" ${d.slug==='ti'?'selected':''}>${escape(d.name)}</option>`).join(''); content.innerHTML=`<div class="page narrow"><div class="form-card"><h1>Novo chamado</h1><p class="subtitle">Este chamado será identificado automaticamente com os dados deste computador.</p><form id="ticket-form"><div class="form-grid"><div class="field"><label for="title">Título</label><input id="title" lang="pt-BR" spellcheck="true" maxlength="180" required placeholder="Ex.: Mouse sem clique"></div><div class="field"><label for="department">Enviar para</label><select id="department" required>${options}</select></div></div><div class="field"><label for="description">Descrição</label><textarea id="description" lang="pt-BR" spellcheck="true" maxlength="8000" placeholder="Descreva o problema com o máximo de detalhes…"></textarea><span class="hint">Palavras não reconhecidas aparecem sublinhadas; clique com o botão direito para ver sugestões.</span></div><div class="form-grid"><div class="field"><label for="priority">Prioridade</label><select id="priority"><option value="normal">Normal</option><option value="low">Baixa</option><option value="high">Alta</option></select></div><div class="field"><label>Computador</label><input disabled value="${escape(state.boot?.hostname||'Identificando…')}"></div></div><div class="dropzone" id="dropzone" tabindex="0"><strong>Anexar arquivos</strong><p>Arraste arquivos aqui, escolha arquivos ou cole uma captura de tela com <kbd>Ctrl</kbd> + <kbd>V</kbd>. Limite de 8 MB por arquivo.</p><input id="attachments" type="file" multiple hidden><button type="button" class="file-button" id="select-files">Escolher arquivos</button><div class="file-list" id="file-list"></div></div><div id="form-notice"></div><div class="actions"><button class="big-action" type="submit">Abrir chamado</button><button class="secondary-action" type="button" data-view="home">Cancelar</button></div></form></div></div>`;
    let files=[]; const renderFiles=()=>{ const tooBig=files.find(f=>f.size>8*1024*1024); $('#file-list').innerHTML=tooBig?`<span style="color:#ff9ca5">${escape(tooBig.name)} ultrapassa 8 MB.</span>`:files.map(f=>`• ${escape(f.name)} (${Math.ceil(f.size/1024)} KB)`).join(''); }; const addFiles=incoming=>{for(const file of [...incoming].filter(Boolean)){if(!files.some(old=>old.name===file.name&&old.size===file.size&&old.lastModified===file.lastModified))files.push(file);}renderFiles();}; $('#select-files').onclick=()=>$('#attachments').click(); $('#attachments').onchange=e=>addFiles(e.target.files); const dropzone=$('#dropzone'); ['dragenter','dragover'].forEach(type=>dropzone.addEventListener(type,e=>{e.preventDefault();dropzone.classList.add('dragging');})); ['dragleave','drop'].forEach(type=>dropzone.addEventListener(type,e=>{e.preventDefault();dropzone.classList.remove('dragging');})); dropzone.addEventListener('drop',e=>addFiles(e.dataTransfer.files)); document.onpaste=e=>{if(state.view!=='new')return;const pasted=[...(e.clipboardData?.files||[])].filter(file=>file.type.startsWith('image/'));if(pasted.length){e.preventDefault();addFiles(pasted);dropzone.focus();}};
    $('#ticket-form').onsubmit=async e=>{e.preventDefault(); const notice=$('#form-notice'); const submit=$('[type=submit]',e.target); try{submit.disabled=true;submit.textContent='Abrindo chamado…'; const attachments=await Promise.all(files.map(readFile)); const ticket=await app().CreateTicket({title:$('#title').value,description:$('#description').value,priority:$('#priority').value,department:$('#department').value,attachments}); state.mine.unshift(ticket); state.selected=ticket; state.view='detail'; renderSidebar(); renderDetail(ticket); }catch(err){notice.innerHTML=`<div class="notice error">${escape(err)}</div>`;}finally{submit.disabled=false;submit.textContent='Abrir chamado';}}; bindViews(); }
  function readFile(file){ if(file.size>8*1024*1024) return Promise.reject(`O arquivo ${file.name} ultrapassa 8 MB.`); return new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=()=>reject(`Não foi possível ler ${file.name}.`);r.onload=()=>resolve({filename:file.name,content_base64:String(r.result).split(',')[1]||''});r.readAsDataURL(file);}); }
  function renderReceived(){ const depts=state.boot?.departments||[]; const nameFor=s=>depts.find(d=>d.slug===s)?.name||s; const open=state.received.filter(t=>t.status!=='done'); content.innerHTML=`<div class="page"><div class="received-head"><div><h1>Chamados recebidos</h1><p class="subtitle">Solicitações destinadas aos setores que este computador atende.</p></div><div class="department-pills">${(state.boot?.receive_departments||[]).map(s=>`<span class="department-pill">${escape(nameFor(s))}</span>`).join('')}</div></div><div class="received-list">${open.length?open.map(t=>`<article class="received-card ${t.priority==='high'?'high':''}"><div class="accent"></div><div class="received-body"><div class="ticket-meta"><span>${escape(t.code)} · ${escape(nameFor(t.department))}</span><span>${escape(priorityText[t.priority]||t.priority)}</span></div><h3>${escape(t.title)}</h3><p>${escape(t.owner_name_snapshot||'Usuário não identificado')} · ${escape(t.hostname_snapshot||'PC não identificado')} · ${relative(t.created_at)}</p>${ticketStatus(t)}</div><div class="received-side"><button class="open-button" data-open="${escape(t.id)}">Abrir</button></div></article>`).join(''):'<div class="form-card"><strong>Nenhum chamado recebido em aberto.</strong><p class="muted">Os novos chamados aparecerão aqui automaticamente.</p></div>'}</div></div>`; $$('[data-open]').forEach(b=>b.onclick=()=>openTicket(b.dataset.open)); }
  async function openTicket(id){ try{ content.innerHTML=$('#loading-template').innerHTML; const item=await app().Ticket(id); state.selected=item; state.view='detail'; renderSidebar(); renderDetail(item); }catch(err){showError(err);} }
  function renderDetail(t){ const isReceived=state.received.some(x=>x.id===t.id); const depts=state.boot?.departments||[]; const department=depts.find(d=>d.slug===t.department)?.name||t.department; content.innerHTML=`<div class="page"><button class="back" data-view="${isReceived?'received':'home'}">← Voltar</button><div class="detail-card" style="margin-top:14px"><div class="detail-header"><div><div class="ticket-meta"><span>${escape(t.code)} · ${escape(department)}</span><span class="priority ${t.priority==='high'?'high':''}">${escape(priorityText[t.priority]||t.priority)}</span></div><h1>${escape(t.title)}</h1><p class="subtitle" style="margin:0">Aberto por <strong>${escape(t.owner_name_snapshot||'Usuário do computador')}</strong> · ${escape(t.hostname_snapshot||'PC')} · ${date(t.created_at)}</p></div></div><div class="detail-grid"><div><h3>Descrição</h3><div class="detail-description">${escape(t.description||'Sem descrição adicional.')}</div><section class="timeline"><h3>Conversas</h3><div id="comments">${(t.comments||[]).length?t.comments.map(c=>`<article class="comment"><strong>${escape(c.author_name||c.author_role||'Usuário')}</strong><small> · ${date(c.created_at)}</small><p>${escape(c.body)}</p></article>`).join(''):'<p class="muted">Nenhuma mensagem ainda.</p>'}</div><form class="comment-form" id="comment-form"><input id="comment-body" maxlength="4000" placeholder="Escreva uma resposta…"><button>Enviar</button></form></section></div><aside><h3>Status</h3><select class="status-select" id="status"><option value="open" ${t.status==='open'?'selected':''}>Aberto</option><option value="in_progress" ${t.status==='in_progress'?'selected':''}>Em andamento</option><option value="waiting" ${t.status==='waiting'?'selected':''}>Aguardando</option>${isReceived?`<option value="done" ${t.status==='done'?'selected':''}>Concluir</option>`:''}</select>${isReceived?`<div class="field"><label for="resolution">Resolução ao concluir</label><textarea id="resolution" placeholder="Descreva o que foi realizado…"></textarea></div><button class="big-action" id="save-status" style="margin-top:14px;width:100%">Salvar andamento</button>`:'<p class="hint">Você acompanha este chamado; o setor responsável atualiza o andamento.</p>'}<hr style="border:0;border-top:1px solid var(--line-soft);margin:22px 0"><p class="hint">Última atualização<br><strong>${date(t.updated_at)}</strong></p></aside></div></div></div>`; $('#comment-form').onsubmit=async e=>{e.preventDefault();try{const updated=await app().AddComment(t.id,$('#comment-body').value);replaceTicket(updated);renderDetail(updated);}catch(err){showError(err);}}; if(isReceived){$('#save-status').onclick=async()=>{try{const updated=await app().UpdateTicket(t.id,$('#status').value,$('#resolution').value);replaceTicket(updated);renderSidebar();renderDetail(updated);}catch(err){showError(err);}};} bindViews(); }
  function replaceTicket(ticket){ state.mine=state.mine.map(x=>x.id===ticket.id?ticket:x); state.received=state.received.map(x=>x.id===ticket.id?ticket:x); state.selected=ticket; }
  function showError(error){ content.innerHTML=`<div class="page narrow"><div class="form-card"><h1>Não foi possível concluir</h1><div class="notice error">${escape(error)}</div><button class="big-action" data-view="home">Voltar aos meus chamados</button></div></div>`;bindViews(); }
  function bindViews(){ $$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view)); }
  async function navigate(view){ state.view=view; state.selected=null; if(view==='new')return renderNew(); if(view==='received')return renderReceived(); renderHome(); }
  async function refresh(silent=false){ try{const boot=await app().RefreshRouting(); if(!boot.connected)throw boot.message||'Não foi possível atualizar a configuração deste computador.'; state.boot=boot; setConnection(true,boot.message); $('#device-name').textContent=`Este computador: ${boot.hostname}`; const [mine,received]=await Promise.all([app().MyTickets(),app().ReceivedTickets()]); const newReceived=received.filter(t=>!state.seen.has(t.id)&&t.status!=='done'); state.mine=mine; state.received=received; received.forEach(t=>state.seen.add(t.id)); renderSidebar(); if(!state.initialReceived){for(const t of newReceived){app().Notify('Novo chamado recebido',`${t.title} — ${t.hostname_snapshot||'Computador não identificado'}`).catch(()=>{});}} state.initialReceived=false; if(!silent){if(state.view==='received')renderReceived();else if(state.view==='home')renderHome();}}catch(err){setConnection(false,String(err));if(!silent)showError(err);} }
  async function init(){ content.innerHTML=$('#loading-template').innerHTML; try{const boot=await app().Bootstrap(); state.boot=boot; setConnection(boot.connected,boot.message); $('#device-name').textContent=boot.connected?`Este computador: ${boot.hostname}`:'Computador não conectado'; if(!boot.connected)throw boot.message||'Não foi possível conectar.'; await refresh(true); renderHome();}catch(err){showError(err);} }
  $('#refresh').onclick=()=>refresh(false); $$('.filter').forEach(b=>b.onclick=()=>{state.status=b.dataset.status;$$('.filter').forEach(x=>x.classList.toggle('active',x===b));renderSidebar();});$$('.period').forEach(b=>b.onclick=()=>{state.period=b.dataset.period;$$('.period').forEach(x=>x.classList.toggle('active',x===b));renderSidebar();});
  init(); setInterval(()=>refresh(true),10000);
})();
